Func<Orc.Cards.CardEventView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{

    if (view.Host is not Orc.Game.Cards.UnitCard self || view.Unit is not Orc.Game.Cards.UnitCard unit) { return; }
    if (!object.ReferenceEquals(unit, self)) { return; }

    var runtime = Orc.Game.Effects.EffectRuntime.ResolveFor(self);
    var service = Orc.Game.MatchCardService.ResolveFor(self);
    var random = Orc.Game.MatchRandomService.ResolveFor(self);
    var engine = ctx.Engine;
    if (runtime is null || service is null || random is null || engine is null) { return; }

    Func<Orc.Cards.Card, Orc.Game.Players.Player?> ownerOf = c =>
    {
        if (c is Orc.Game.Players.Hq hq) { return hq.Owner; }
        if (c is Orc.Game.Cards.CardBase cb) { return cb.Owner; }
        return null;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onField = u =>
        u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) && !st.IsDestroyed && st.Line is not null;

    Func<Orc.Game.Cards.UnitCard, bool> isInfantry = u =>
    {
        foreach (var t in u.Definition.UnitTypes)
        {
            if (string.Equals(t, "infantry", System.StringComparison.OrdinalIgnoreCase)) { return true; }
        }
        return false;
    };

    Func<Orc.Game.Cards.UnitCard, bool> onFrontLine = u =>
    {
        if (!u.TryGetData<Orc.Game.Cards.UnitStateData>(out var st) || st.IsDestroyed || st.Line is null)
        {
            return false;
        }
        return st.Line.Name.Contains("前线", System.StringComparison.Ordinal);
    };

    if (!ctx.TryGet(Orc.Game.GameUpdates.PayloadNewPosition, out var rawNew)
        || rawNew is not Orc.Game.Board.Slot newSlot
        || !newSlot.Name.Contains("前线", System.StringComparison.Ordinal))
    {
        return;
    }

    if (ctx.TryGet(Orc.Game.GameUpdates.PayloadOldPosition, out var rawOld)
        && rawOld is Orc.Game.Board.Slot oldSlot
        && oldSlot.Name.Contains("前线", System.StringComparison.Ordinal))
    {
        return;
    }

    var owner = self.Owner;
    if (owner is null) { return; }

    // 手中花费 <=2 的步兵（无交互选牌面：随机取 1 张）。
    var handUnits = new System.Collections.Generic.List<Orc.Game.Cards.UnitCard>();
    foreach (var c in owner.Hand)
    {
        if (c is Orc.Game.Cards.UnitCard uc && uc.Definition.DeployCost <= 2 && isInfantry(uc)) { handUnits.Add(uc); }
    }

    if (handUnits.Count == 0) { return; }

    var pick = random.PickOne(handUnits);
    var slots = service.GetAdjacentEmptySlots(owner);
    if (slots.Count == 0) { return; }

    owner.Hand.Remove(pick);
    await service.PlaceToSupportLineAsync(pick, owner, slots[0], ct);
    if (!onField(pick)) { return; }

    await runtime.MoveAsync(pick, "frontline", ct);
};
